import { Component, OnInit } from '@angular/core';
import { CoursesStoreService } from '@app/services/courses-store.service';
import { mockedCoursesList } from '@app/shared/mocks/mocks';
import { Observable } from 'rxjs';

interface Course {
  id: string;
  title: string;
  description: string;
  creationDate: string | Date;
  duration: number;
  authors: string[];
}

@Component({
  selector: 'app-course',
  templateUrl: './course.component.html',
  styleUrls: ['./course.component.css']
})
export class CourseComponent implements OnInit {
  courses$: Observable<Course[]> = this.coursesStore.courses$;
  filteredCourses: Course[] = [];
  editable = true;

  constructor(private coursesStore: CoursesStoreService) {}

  ngOnInit() {
    this.coursesStore.getAll();
    this.courses$.subscribe(courses => {
      this.filteredCourses = courses;
    });
  }

  onSearch(query: string) {
    if (!query) {
      this.coursesStore.getAll();
    } else {
      this.coursesStore.filterCourses(query);
    }
  }

  getAuthorNames(authors: string[]) {
    return authors.join(', ');
  }

  onShow(title: string) {
    console.log('Show course:', title);
  }

  onEdit(title: string) {
    console.log('Edit course:', title);
  }

  onDelete(title: string) {
    console.log('Delete course:', title);
  }
}
